import { EVENT_ACTIONS } from '@proton/shared/lib/constants';

import { useEventManager } from '../../hooks';

/**
 * After the Chargebee migration, certain objects aren't immediately updated.
 * For example, it takes a few seconds for updated Subscription object to appear.
 * This time isn't predictable due to async nature of the backend system, so we need to poll for the updated data.
 * */
export const interval = 5000;
export const maxPollingSteps = 5;

export const usePollEvents = () => {
    const eventManager = useEventManager();

    return (property?: string, action?: EVENT_ACTIONS): Promise<void> =>
        new Promise((resolve, reject) => {
            let finished = false;
            let attempts = 0;
            let timeout: ReturnType<typeof setTimeout> | undefined;
            let unsubscribe: (() => void) | undefined;

            const finish = (error?: unknown) => {
                if (finished) {
                    return;
                }
                finished = true;
                if (timeout !== undefined) {
                    clearTimeout(timeout);
                }
                unsubscribe?.();
                if (error !== undefined) {
                    reject(error);
                } else {
                    resolve();
                }
            };

            if (property) {
                unsubscribe = eventManager.subscribe(
                    (event: Record<string, { Action: EVENT_ACTIONS }[] | undefined>) => {
                        if (finished) {
                            return;
                        }
                        if (event[property]?.some(({ Action }) => action === undefined || Action === action)) {
                            finish();
                        }
                    }
                );
                // A subscription can deliver an event before returning its cleanup function.
                if (finished) {
                    unsubscribe();
                    return;
                }
            }

            const poll = async () => {
                if (finished) {
                    return;
                }
                attempts += 1;
                try {
                    await eventManager.call();
                    if (finished) {
                        return;
                    }
                    if (attempts === maxPollingSteps) {
                        finish();
                    } else {
                        timeout = setTimeout(poll, interval);
                    }
                } catch (error) {
                    finish(error);
                }
            };

            timeout = setTimeout(poll, interval);
        });
};
